import * as Tone from 'tone';
import { getMetronomePlaybackPatterns, MetronomeSettings } from './metronome';
import { getTotalDuration, getPlaybackPatternsForNoteGroup } from './note';
import { PlaybackPattern, Pitch } from './note-definition';
import { TimeSignature, TimeSignatureComplexity } from './time-signature';
import { Measure } from './vex';

export enum PlaybackState {
  PLAYING,
  STOPPED,
}
export type NoteTriggerHandler = (index: number | null) => void;

const toneDurationFactorNoteSpacingMap: { [toneDuration: string]: number } = {
  '1': 0.9,
  '2': 0.875,
  '4': 0.75,
  '8': 0.67,
  '16': 0.5,
  '32': 0.1,
};

const NOTE_SPACING = 0.75; // %
const HEADING_TIME = 0.1; // seconds
const TRAILING_TIME = 1; // seconds

export const Transport = Tone.Transport;

// Any monophonic Tone instrument that exposes triggerAttackRelease. Both the
// bass playback voice and the metronome click use the same trigger helpers.
type TriggerableSynth = Tone.MonoSynth | Tone.MembraneSynth;

// Percussive bass "pluck": a low triangle voice with a fast filter envelope,
// so each note has a defined attack that quickly decays away instead of the
// thin, sustained tone of the default Tone.Synth.
const getPlaybackSynth = (): TriggerableSynth => {
  const synth = new Tone.MonoSynth({
    oscillator: { type: 'triangle' },
    envelope: {
      attack: 0.005,
      decay: 0.28,
      sustain: 0.25,
      release: 0.4,
    },
    filterEnvelope: {
      attack: 0.005,
      decay: 0.18,
      sustain: 0.05,
      release: 0.3,
      baseFrequency: 90,
      octaves: 3.5,
      exponent: 2,
    },
  }).toDestination();

  synth.filter.Q.value = 2;

  return synth;
};

// Dry metronome click: a short MembraneSynth "tick" with almost no pitch
// decay and a very short amplitude envelope, so it reads as a percussive
// click rather than a piercing sine beep.
const getMetronomeSynth = (): TriggerableSynth => {
  const synth = new Tone.MembraneSynth({
    pitchDecay: 0.008,
    octaves: 2,
    envelope: {
      attack: 0.001,
      decay: 0.05,
      sustain: 0,
      release: 0.02,
    },
  }).toDestination();

  return synth;
};

export const startPlayback = (
  measures: Measure[],
  pitch: Pitch,
  timeSignature: TimeSignature,
  metronomeSettings: MetronomeSettings,
  onNoteTrigger: NoteTriggerHandler,
  onMetronomeClickTrigger: NoteTriggerHandler,
  // Number of times to play the rhythm. Use Infinity to loop until stopped.
  repeat: number = 1
) => {
  Tone.start();
  Transport.cancel();
  Transport.loop = false;

  Transport.timeSignature = timeSignature.beatsPerMeasure;

  const isInfinite = !isFinite(repeat);
  const passes = isInfinite ? 1 : Math.max(1, Math.floor(repeat));

  const playbackSynth = getPlaybackSynth();
  const metronomeSynth = metronomeSettings.active ? getMetronomeSynth() : null;

  let elapsedTime = HEADING_TIME;

  // Count-off clicks play once, before the repeated/looped body.
  if (metronomeSynth && metronomeSettings.countOffMeasures) {
    scheduleMetronomeMeasures(
      metronomeSettings.countOffMeasures,
      metronomeSynth,
      elapsedTime,
      timeSignature,
      metronomeSettings,
      onMetronomeClickTrigger
    );

    let countOffTime = Tone.Time(
      `${metronomeSettings.countOffMeasures}m`
    ).toSeconds();

    if (timeSignature.complexity === TimeSignatureComplexity.ALLA_BREVE) {
      countOffTime = countOffTime / 2;
    }

    elapsedTime += countOffTime;
  }

  const bodyStart = elapsedTime;
  let bodyEnd = bodyStart;

  for (let pass = 0; pass < passes; pass++) {
    if (metronomeSynth) {
      scheduleMetronomeMeasures(
        measures.length,
        metronomeSynth,
        elapsedTime,
        timeSignature,
        metronomeSettings,
        onMetronomeClickTrigger
      );
    }

    elapsedTime = scheduleMeasures(
      elapsedTime,
      playbackSynth,
      measures,
      pitch,
      timeSignature,
      onNoteTrigger
    );

    if (pass === 0) {
      bodyEnd = elapsedTime;
    }
  }

  if (isInfinite) {
    // Loop the single scheduled body; count-off (before bodyStart) plays once.
    Transport.loopStart = bodyStart;
    Transport.loopEnd = bodyEnd;
    Transport.loop = true;
  } else {
    Transport.schedule(() => onNoteTrigger(null), elapsedTime);
    Transport.schedule(stopPlayback, elapsedTime + TRAILING_TIME);
  }

  Transport.start();
};

export const stopPlayback = () => {
  Transport.stop();
  Transport.loop = false;
};

export const updateTempo = (tempo: number) => {
  Transport.bpm.value = tempo;
};

const getPitchString = (pitch: Pitch) => {
  return `${pitch.pitchClass}${pitch.octave}`;
};

const triggerNote = (
  synth: TriggerableSynth,
  playbackPattern: PlaybackPattern,
  index: number,
  pitch: Pitch,
  onNoteTrigger: NoteTriggerHandler
) => {
  return (time: number) => {
    onNoteTrigger(index);
    if (!playbackPattern.rest) {
      let timeToAdd = Tone.Time(playbackPattern.toneDuration).toSeconds();

      // Tone.js treats `1n` (the whole note) as a whole measure, regardless of time signature.
      // Convert it to be strictly 4 beats
      if (playbackPattern.toneDuration === '1n') {
        timeToAdd = Tone.Time('4n').toSeconds() * 4;
      }

      // Handle dotted whole notes similarly
      if (playbackPattern.toneDuration === '1n.') {
        timeToAdd = Tone.Time('4n').toSeconds() * 6;
      }

      const toneDurationFactor = playbackPattern.toneDuration.replace(
        /\D/g,
        ''
      );

      const noteSpacing = toneDurationFactorNoteSpacingMap[toneDurationFactor];

      synth.triggerAttackRelease(
        getPitchString(pitch),
        timeToAdd * noteSpacing,
        time,
        playbackPattern.velocity
      );
    }
  };
};

// Schedules a single pass of the measures starting at `elapsedTime` and
// returns the time at which the pass ends. Note-highlight indices restart at 0
// each pass so every repeat highlights the same rendered note heads. Scheduling
// of the end-of-playback reset/stop is handled by the caller.
const scheduleMeasures = (
  elapsedTime: number,
  synth: TriggerableSynth,
  measures: Measure[],
  pitch: Pitch,
  timeSignature: TimeSignature,
  onNoteTrigger: NoteTriggerHandler
): number => {
  if (measures.length === 0) {
    return elapsedTime;
  }

  let playbackPatternIndex = 0;

  measures.forEach((measure) => {
    if (getTotalDuration(measure.noteGroups) === 0) {
      return;
    }

    measure.noteGroups.forEach((noteGroup) => {
      const playbackPatterns = getPlaybackPatternsForNoteGroup(
        noteGroup,
        timeSignature
      );

      if (playbackPatterns.length === 0) {
        return;
      }

      playbackPatterns.forEach((playbackPattern) => {
        Transport.schedule(
          triggerNote(
            synth,
            playbackPattern,
            playbackPatternIndex,
            pitch,
            onNoteTrigger
          ),
          elapsedTime
        );

        let timeToAdd = Tone.Time(playbackPattern.toneDuration).toSeconds();

        // Tone.js treats `1n` (the whole note) as a whole measure, regardless of time signature.
        // Convert it add strictly 4 beats of time. However, whole rests should take up the whole
        // measure, so no need to apply this behavior if the note is a rest
        if (playbackPattern.toneDuration === '1n' && !playbackPattern.rest) {
          timeToAdd = Tone.Time('4n').toSeconds() * 4;
        }

        // Handle dotted whole notes similarly
        if (playbackPattern.toneDuration === '1n.') {
          timeToAdd = Tone.Time('4n').toSeconds() * 6;
        }

        elapsedTime += timeToAdd;
        playbackPatternIndex += 1;
      });
    });
  });

  return elapsedTime;
};

const scheduleMetronome = (
  synth: TriggerableSynth,
  elapsedTime: number,
  timeSignature: TimeSignature,
  metronomeSettings: MetronomeSettings,
  scheduleNext: boolean,
  onMetronomeClickTrigger: NoteTriggerHandler
) => {
  const playbackPatterns = getMetronomePlaybackPatterns(
    timeSignature,
    metronomeSettings
  );

  playbackPatterns.forEach((playbackPattern, index) => {
    if (playbackPattern.pitch) {
      Transport.schedule(
        triggerNote(
          synth,
          playbackPattern,
          index,
          playbackPattern.pitch,
          (i) => {
            // Schedule next measure of clicks if scheduling last click
            if (scheduleNext && i === playbackPatterns.length - 1) {
              scheduleMetronome(
                synth,
                elapsedTime,
                timeSignature,
                metronomeSettings,
                true,
                onMetronomeClickTrigger
              );
            }

            onMetronomeClickTrigger(i);
          }
        ),
        elapsedTime
      );
    }

    elapsedTime += Tone.Time(playbackPattern.toneDuration).toSeconds();
  });

  return elapsedTime;
};

const scheduleMetronomeMeasures = (
  measureCount: number,
  synth: TriggerableSynth,
  elapsedTime: number,
  timeSignature: TimeSignature,
  metronomeSettings: MetronomeSettings,
  onMetronomeClickTrigger: NoteTriggerHandler
) => {
  for (let count = 0; count < measureCount; count++) {
    elapsedTime = scheduleMetronome(
      synth,
      elapsedTime,
      timeSignature,
      metronomeSettings,
      false,
      onMetronomeClickTrigger
    );
  }
};

export const startMetronome = (
  timeSignature: TimeSignature,
  metronomeSettings: MetronomeSettings,
  onMetronomeClickTrigger: NoteTriggerHandler
) => {
  Tone.start();
  Transport.cancel();

  scheduleMetronome(
    getMetronomeSynth(),
    HEADING_TIME,
    timeSignature,
    metronomeSettings,
    true,
    onMetronomeClickTrigger
  );

  Transport.start();
};

export const stopMetronome = () => {
  Transport.stop();
  Transport.cancel();
};
