import React, { useContext, useEffect } from 'react';
import classnames from 'classnames';
import { NoteTriggerHandler, PlaybackState } from '../modules/tone';
import { Measure } from '../modules/vex';
import {
  Transport,
  startPlayback,
  stopPlayback,
  updateTempo,
} from '../modules/tone';
import { buildBemClassName } from '../modules/util';
import { AppContext } from '../App';
import { useTranslation } from 'react-i18next';

export interface PlayerProps {
  measures: Measure[];
  playbackState: PlaybackState;
  metronomeOn: boolean;
  repeat: number;
  // Incremented by the parent to request (re)starting playback, used to keep
  // playing when auto mode advances to the next rhythm.
  autoPlayRequest: number;
  className?: string;
  onPlaybackStateChange: PlaybackStateChangeHandler;
  onNoteTrigger: NoteTriggerHandler;
  onMetronomeClickTrigger: NoteTriggerHandler;
  onManualStop: () => void;
}

export type PlaybackStateChangeHandler = (playbackState: PlaybackState) => void;

const buildClassName = buildBemClassName('c-rr-player');

const Player = ({
  measures,
  playbackState,
  metronomeOn,
  repeat,
  autoPlayRequest,
  className = '',
  onPlaybackStateChange,
  onNoteTrigger,
  onMetronomeClickTrigger,
  onManualStop,
}: PlayerProps) => {
  const { t } = useTranslation();
  const { state } = useContext(AppContext);

  const {
    tempo,
    pitch,
    timeSignature,
    metronomeSettings,
  } = state.scoreSettings;

  const stopHandler = () => {
    onPlaybackStateChange(PlaybackState.STOPPED);
    Transport.off('stop', stopHandler);
  };

  // Set tempo when it changes
  useEffect(() => {
    updateTempo(tempo);
  }, [tempo]);

  const startPlaybackNow = () => {
    startPlayback(
      measures,
      pitch,
      timeSignature,
      metronomeSettings,
      onNoteTrigger,
      onMetronomeClickTrigger,
      repeat
    );
    onPlaybackStateChange(PlaybackState.PLAYING);
    Transport.on('stop', stopHandler);
  };

  // Auto mode bumps autoPlayRequest to (re)start playback of the promoted
  // rhythm; ignore the initial value of 0.
  useEffect(() => {
    if (autoPlayRequest > 0) {
      startPlaybackNow();
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [autoPlayRequest]);

  const handlePlayToggle = () => {
    if (playbackState === PlaybackState.STOPPED) {
      startPlaybackNow();
    } else {
      onManualStop();
      stopPlayback();
    }
  };

  return (
    <div className={buildClassName()()}>
      <button
        type="button"
        className={classnames(
          className,
          'c-rr-button',
          'c-rr-button--dark',
          buildClassName('play-toggle')()
        )}
        onClick={handlePlayToggle}
        disabled={metronomeOn}
      >
        {playbackState === PlaybackState.PLAYING
          ? t('stopPlayback')
          : t('startPlayback')}
      </button>
    </div>
  );
};

export default Player;
